#include "rinkfit/augmented_lagrangian.hpp"
#include <ceres/ceres.h>
#include <nlohmann/json.hpp>
#include <iostream>
#include <fstream>
#include <cmath>
using namespace rinkfit;
struct QConstraint{double q;template<class T>bool operator()(const T*b,T*r)const{r[0]=T(q)-b[0];return true;}};
struct Budget{template<class T>bool operator()(const T*b,T*r)const{using std::sqrt;r[0]=sqrt(T(2)*b[0]+T(1));return true;}};
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("need Q and report.json");double q=std::stod(argv[1]);nlohmann::json out;out["source_q"]=q;out["model"]= "single frozen q-b numerical stress test; actual physical maximum can be supplied; not a physical fit";
 double x=q;ceres::Problem base;auto id=static_cast<ceres::ResidualBlockId>(add_phr_inequality(base,std::make_unique<ceres::AutoDiffCostFunction<QConstraint,1,1>>(new QConstraint{q}),{&x},0.,1.));const auto* baseline=base.GetCostFunctionForResidualBlock(id);ceres::Problem active_problem;auto cid=static_cast<ceres::ResidualBlockId>(add_phr_inequality(active_problem,std::make_unique<ceres::AutoDiffCostFunction<QConstraint,1,1>>(new QConstraint{q}),{&x},0.,1.,true));const auto* candidate=active_problem.GetCostFunctionForResidualBlock(cid);double r0,r1,j0,j1;double const*P[]={&x};double*J0[]={&j0};double*J1[]={&j1};baseline->Evaluate(P,&r0,J0);candidate->Evaluate(P,&r1,J1);
 if(r0!=0||r1!=0||j0!=0||j1!=-1.)throw std::runtime_error("kink residual/Jacobian expectations failed");out["kink"]={{"baseline_J",j0},{"candidate_J",j1},{"left_residual_derivative",-1},{"right_residual_derivative",0},{"baseline_full_objective_gradient",1+j0*r0},{"candidate_full_objective_gradient",1+j1*r1}};
 x=q-1e-4;candidate->Evaluate(P,&r0,nullptr);double left=(0.-r0)/(q-x);x=q+1e-4;candidate->Evaluate(P,&r1,nullptr);double right=r1/(x-q);if(std::abs(left+1.)>1e-12||right!=0.)throw std::runtime_error("one-sided derivatives failed");out["measured_one_sided_derivatives"]={left,right};
 double max_value_diff=0,max_objective_diff=0;for(double d:{-2.,-1.,-1e-4,0.,1e-4,1.,2.}){x=q+d;baseline->Evaluate(P,&r0,J0);candidate->Evaluate(P,&r1,J1);max_value_diff=std::max(max_value_diff,std::abs(r0-r1));max_objective_diff=std::max(max_objective_diff,std::abs((x+.5*r0*r0)-(x+.5*r1*r1)));}out["max_residual_difference"]=max_value_diff;out["max_exact_objective_difference"]=max_objective_diff;if(max_value_diff!=0||max_objective_diff!=0)throw std::runtime_error("objective changed");
 for(bool active:{false,true}){double b=q;ceres::Problem p;p.AddParameterBlock(&b,1);p.SetParameterLowerBound(&b,0,0.);p.AddResidualBlock(new ceres::AutoDiffCostFunction<Budget,1,1>(new Budget),nullptr,&b);add_phr_inequality(p,std::make_unique<ceres::AutoDiffCostFunction<QConstraint,1,1>>(new QConstraint{q}),{&b},0.,1.,active);ceres::Solver::Options o;o.max_num_iterations=40;o.function_tolerance=0;o.parameter_tolerance=0;o.gradient_tolerance=1e-10;o.linear_solver_type=ceres::SPARSE_NORMAL_CHOLESKY;o.sparse_linear_algebra_library_type=ceres::SUITE_SPARSE;ceres::Solver::Summary s;ceres::Solve(o,&p,&s);out[active?"active_at_kink":"zero_at_kink"]={{"b",b},{"exact_objective_without_constant",b+.5*std::pow(std::max(0.,q-b),2)},{"successful_steps",s.num_successful_steps},{"unsuccessful_steps",s.num_unsuccessful_steps},{"iterations",s.iterations.size()},{"termination",s.BriefReport()}};}
 const auto ca=out["active_at_kink"],ze=out["zero_at_kink"];bool improved=ca["unsuccessful_steps"].get<int>()<ze["unsuccessful_steps"].get<int>();out["improved_rejections"]=improved;out["same_objective_exact_b_star"]=std::max(0.,q-1.);out["candidate_matches_exact_minimum"]=std::abs(ca["b"].get<double>()-(q-1.))<1e-6;out["initial_GN_steps"]={{"zero_at_kink",-(2*q+1)},{"active_at_kink",-1./(1.+1./(2*q+1))}};std::ofstream f(argv[2]);f<<out.dump(2)<<'\n';std::cout<<out.dump()<<'\n';return out["candidate_matches_exact_minimum"].get<bool>()?0:2;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
